ROOT.scriptdef:
CREATE PROCEDURE [CDN].[POS_EksportKraje]
	@rowVersion bigint
AS
BEGIN
	SET NOCOUNT ON;	
	select
		(select max(kpc_id) from cdn.KrajeCelne) as [@RowVersion], (
		select kpc_id as [@Id], kpc_kod as [@Code],KPC_NazwaPL as [@Name], 'true' as [@IsActive] from cdn.KrajeCelne where KPC_Id >@RowVersion
		
	for xml path('Country'), type)
	for xml path('Countries')
	SET NOCOUNT OFF;	
END
